/// Floating-range flood fill per plane, following `floodFill`:
/// the pixel at `(seed_x, seed_y)` takes `value`, and each
/// unmarked pixel joins the region when a connected neighbor
/// already belongs and the candidate's original value lies within
/// `[neighbor - lo_diff, neighbor + up_diff]` of that neighbor's
/// original value. Propagation runs a fixed number of relaxation
/// passes (zero selects `height + width`); regions whose flood
/// diameter exceeds the bound fill partially. The output is a
/// filled copy of the input; unmarked pixels keep their values.
///
/// # Errors
///
/// Returns an error unless the image is a nonempty FP32
/// NCHW/CHW image, the seed is in bounds, and `value`,
/// `lo_diff`, and `up_diff` are finite with `lo_diff >= 0` and
/// `up_diff >= 0`.
#[allow(clippy::too_many_arguments)]
pub fn flood_fill(
	input: &Image,
	seed_x: u32,
	seed_y: u32,
	value: f32,
	lo_diff: f32,
	up_diff: f32,
	connectivity: Connectivity,
	propagation_passes: u32,
) -> Result<Image> {
	let contract = crate::core::operation::image::FLOOD_FILL;
	finite(&[value, lo_diff, up_diff], "image::flood_fill")?;
	if lo_diff < 0.0 || up_diff < 0.0 {
		return Err(Error::invalid_argument(
			"image::flood_fill diffs must be nonnegative",
		));
	}
	let (batch, channels, image_height, image_width) = image_extent(input, contract.name())?;
	if seed_x >= image_width || seed_y >= image_height {
		return Err(Error::invalid_argument(
			"image::flood_fill seed must be in bounds",
		));
	}
	let plane_count = batch
		.checked_mul(channels)
		.ok_or_else(|| Error::out_of_range("image::flood_fill plane count exceeds u32"))?;
	let element_count = u32::try_from(input.as_matrix().num_elements())
		.map_err(|_| Error::out_of_range("image::flood_fill element count exceeds u32"))?;
	let relax_passes = if propagation_passes == 0 {
		image_height
			.checked_add(image_width)
			.ok_or_else(|| Error::out_of_range("image::flood_fill propagation bound exceeds u32"))?
	} else {
		propagation_passes
	};
	let matrix = crate::Matrix::allocate(
		input.runtime(),
		input.as_matrix().shape().to_vec(),
		input.as_matrix().num_elements(),
		DType::F32,
	)?;
	let output = Image::new(matrix, input.layout(), input.format())?;
	let marker = Matrix::allocate(
		input.runtime(),
		vec![
			plane_count as usize,
			image_height as usize,
			image_width as usize,
		],
		element_count as usize,
		DType::U32,
	)?;
	let mut workgroups = KernelId::ImageFloodFillInitF32.output_workgroups(image_width, image_height);
	workgroups[2] = plane_count;
	let init_buffers = [
		BufferBinding::read(input.storage()),
		BufferBinding::write(output.storage()),
		BufferBinding::write(marker.storage()),
	];
	let init_push = [
		PushConstant::U32(batch),
		PushConstant::U32(channels),
		PushConstant::U32(image_height),
		PushConstant::U32(image_width),
		PushConstant::U32(seed_x),
		PushConstant::U32(seed_y),
		PushConstant::F32(value),
	];
	let relax_buffers = [
		BufferBinding::read(input.storage()),
		BufferBinding::read_write(output.storage()),
		BufferBinding::read_write(marker.storage()),
	];
	let relax_push = [
		PushConstant::U32(batch),
		PushConstant::U32(channels),
		PushConstant::U32(image_height),
		PushConstant::U32(image_width),
		PushConstant::U32(connectivity.code()),
		PushConstant::F32(lo_diff),
		PushConstant::F32(up_diff),
		PushConstant::F32(value),
	];
	let mut dispatches = Vec::with_capacity(1 + relax_passes as usize);
	dispatches.push(ComputeDispatch {
		kernel: KernelId::ImageFloodFillInitF32,
		buffers: &init_buffers,
		push_constants: &init_push,
		workgroups,
		indirect: None,
	});
	for _ in 0..relax_passes {
		dispatches.push(ComputeDispatch {
			kernel: KernelId::ImageFloodFillRelaxF32,
			buffers: &relax_buffers,
			push_constants: &relax_push,
			workgroups,
			indirect: None,
		});
	}
	let attributes = [
		unsigned("seed_x", seed_x),
		unsigned("seed_y", seed_y),
		float("value", value),
		float("lo_diff", lo_diff),
		float("up_diff", up_diff),
		enumeration("connectivity", connectivity.token()),
		unsigned("propagation_passes", propagation_passes),
	];
	input.runtime().record_image_split_semantic(
		&dispatches,
		ImageSemanticDispatch {
			contract,
			inputs: &[ImageSemanticInput::Image(input)],
			outputs: &[ImageSemanticOutput::Image(&output)],
			attributes: &attributes,
		},
	)?;
	Ok(output)
}

/// Draw a straight segment over a copy of the input, following `line`:
/// each pixel whose center lies within `thickness / 2` of the
/// `(x1, y1)-(x2, y2)` segment takes `color`; all other pixels copy the
/// input. Coordinates are continuous pixel units and `color` applies to
/// every plane. No anti-aliasing is applied.
///
/// # Errors
///
/// Returns an error unless the image is a nonempty FP32 NCHW/CHW image,
/// all coordinates and `color` are finite, and `thickness` is positive
/// and finite.
#[allow(clippy::too_many_arguments)]
pub fn draw_line(
	input: &Image,
	x1: f32,
	y1: f32,
	x2: f32,
	y2: f32,
	color: f32,
	thickness: f32,
) -> Result<Image> {
	let contract = crate::core::operation::image::DRAW_LINE;
	finite(&[x1, y1, x2, y2, color, thickness], "image::draw_line")?;
	if thickness <= 0.0 {
		return Err(Error::invalid_argument(
			"image::draw_line thickness must be positive",
		));
	}
	let (batch, channels, image_height, image_width) = image_extent(input, contract.name())?;
	let element_count = u32::try_from(input.as_matrix().num_elements())
		.map_err(|_| Error::out_of_range("image::draw_line element count exceeds u32"))?;
	let matrix = crate::Matrix::allocate(
		input.runtime(),
		input.as_matrix().shape().to_vec(),
		input.as_matrix().num_elements(),
		DType::F32,
	)?;
	let output = Image::new(matrix, input.layout(), input.format())?;
	input.runtime().record_image_semantic(
		ComputeDispatch {
			kernel: KernelId::ImageDrawLineF32,
			buffers: &[
				BufferBinding::read(input.storage()),
				BufferBinding::write(output.storage()),
			],
			push_constants: &[
				PushConstant::U32(batch),
				PushConstant::U32(channels),
				PushConstant::U32(element_count),
				PushConstant::U32(image_height),
				PushConstant::U32(image_width),
				PushConstant::F32(x1),
				PushConstant::F32(y1),
				PushConstant::F32(x2),
				PushConstant::F32(y2),
				PushConstant::F32(color),
				PushConstant::F32(thickness),
			],
			workgroups: KernelId::ImageDrawLineF32.linear_workgroups(element_count),
			indirect: None,
		},
		ImageSemanticDispatch {
			contract,
			inputs: &[ImageSemanticInput::Image(input)],
			outputs: &[ImageSemanticOutput::Image(&output)],
			attributes: &[
				float("x1", x1),
				float("y1", y1),
				float("x2", x2),
				float("y2", y2),
				float("color", color),
				float("thickness", thickness),
			],
		},
	)?;
	Ok(output)
}

/// Draw a rectangle border or fill over a copy of the input, following
/// `rectangle`: `(x, y)` gives the top-left corner in pixel units and
/// `width`/`height` the extent. A positive `thickness` draws a border
/// band that many pixels wide measured inward from the rectangle edge;
/// a nonpositive `thickness` fills the rectangle. `color` applies to
/// every plane.
///
/// # Errors
///
/// Returns an error unless the image is a nonempty FP32 NCHW/CHW image,
/// all coordinates and `color` are finite, `width` and `height` are
/// positive, and `thickness` is finite and nonzero.
#[allow(clippy::too_many_arguments)]
pub fn draw_rectangle(
	input: &Image,
	x: f32,
	y: f32,
	width: f32,
	height: f32,
	color: f32,
	thickness: f32,
) -> Result<Image> {
	let contract = crate::core::operation::image::DRAW_RECTANGLE;
	finite(
		&[x, y, width, height, color, thickness],
		"image::draw_rectangle",
	)?;
	if width <= 0.0 || height <= 0.0 {
		return Err(Error::invalid_argument(
			"image::draw_rectangle width and height must be positive",
		));
	}
	if thickness == 0.0 {
		return Err(Error::invalid_argument(
			"image::draw_rectangle thickness must be nonzero",
		));
	}
	let (batch, channels, image_height, image_width) = image_extent(input, contract.name())?;
	let element_count = u32::try_from(input.as_matrix().num_elements())
		.map_err(|_| Error::out_of_range("image::draw_rectangle element count exceeds u32"))?;
	let matrix = crate::Matrix::allocate(
		input.runtime(),
		input.as_matrix().shape().to_vec(),
		input.as_matrix().num_elements(),
		DType::F32,
	)?;
	let output = Image::new(matrix, input.layout(), input.format())?;
	input.runtime().record_image_semantic(
		ComputeDispatch {
			kernel: KernelId::ImageDrawRectangleF32,
			buffers: &[
				BufferBinding::read(input.storage()),
				BufferBinding::write(output.storage()),
			],
			push_constants: &[
				PushConstant::U32(batch),
				PushConstant::U32(channels),
				PushConstant::U32(element_count),
				PushConstant::U32(image_height),
				PushConstant::U32(image_width),
				PushConstant::F32(x),
				PushConstant::F32(y),
				PushConstant::F32(width),
				PushConstant::F32(height),
				PushConstant::F32(color),
				PushConstant::F32(thickness),
			],
			workgroups: KernelId::ImageDrawRectangleF32.linear_workgroups(element_count),
			indirect: None,
		},
		ImageSemanticDispatch {
			contract,
			inputs: &[ImageSemanticInput::Image(input)],
			outputs: &[ImageSemanticOutput::Image(&output)],
			attributes: &[
				float("x", x),
				float("y", y),
				float("width", width),
				float("height", height),
				float("color", color),
				float("thickness", thickness),
			],
		},
	)?;
	Ok(output)
}

/// Draw a circle ring or disk over a copy of the input, following
/// `circle`: `(cx, cy)` is the center in pixel units. A positive
/// `thickness` draws a ring whose band is that many pixels wide around
/// `radius`; a negative `thickness` fills the disk. `color` applies to
/// every plane.
///
/// # Errors
///
/// Returns an error unless the image is a nonempty FP32 NCHW/CHW image,
/// `cx`, `cy`, `radius`, and `color` are finite, `radius` is positive,
/// and `thickness` is finite and nonzero.
pub fn draw_circle(
	input: &Image,
	cx: f32,
	cy: f32,
	radius: f32,
	color: f32,
	thickness: f32,
) -> Result<Image> {
	let contract = crate::core::operation::image::DRAW_CIRCLE;
	finite(&[cx, cy, radius, color, thickness], "image::draw_circle")?;
	if radius <= 0.0 {
		return Err(Error::invalid_argument(
			"image::draw_circle radius must be positive",
		));
	}
	if thickness == 0.0 {
		return Err(Error::invalid_argument(
			"image::draw_circle thickness must be nonzero",
		));
	}
	let (batch, channels, image_height, image_width) = image_extent(input, contract.name())?;
	let element_count = u32::try_from(input.as_matrix().num_elements())
		.map_err(|_| Error::out_of_range("image::draw_circle element count exceeds u32"))?;
	let matrix = crate::Matrix::allocate(
		input.runtime(),
		input.as_matrix().shape().to_vec(),
		input.as_matrix().num_elements(),
		DType::F32,
	)?;
	let output = Image::new(matrix, input.layout(), input.format())?;
	input.runtime().record_image_semantic(
		ComputeDispatch {
			kernel: KernelId::ImageDrawCircleF32,
			buffers: &[
				BufferBinding::read(input.storage()),
				BufferBinding::write(output.storage()),
			],
			push_constants: &[
				PushConstant::U32(batch),
				PushConstant::U32(channels),
				PushConstant::U32(element_count),
				PushConstant::U32(image_height),
				PushConstant::U32(image_width),
				PushConstant::F32(cx),
				PushConstant::F32(cy),
				PushConstant::F32(radius),
				PushConstant::F32(color),
				PushConstant::F32(thickness),
			],
			workgroups: KernelId::ImageDrawCircleF32.linear_workgroups(element_count),
			indirect: None,
		},
		ImageSemanticDispatch {
			contract,
			inputs: &[ImageSemanticInput::Image(input)],
			outputs: &[ImageSemanticOutput::Image(&output)],
			attributes: &[
				float("cx", cx),
				float("cy", cy),
				float("radius", radius),
				float("color", color),
				float("thickness", thickness),
			],
		},
	)?;
	Ok(output)
}

/// Fill a polygon over a copy of the input, following `fillPoly`: the
/// `points` matrix carries `[N, 2]` vertex coordinates and every pixel
/// whose center falls inside the even-odd winding of the polygon takes
/// `color`. `color` applies to every plane.
///
/// # Errors
///
/// Returns an error unless the image is a nonempty FP32 NCHW/CHW image,
/// `points` is an FP32 `[N, 2]` matrix with at least 3 vertices on the
/// same runtime, and `color` is finite.
pub fn fill_polygon(input: &Image, points: &Matrix, color: f32) -> Result<Image> {
	let contract = crate::core::operation::image::FILL_POLYGON;
	if !color.is_finite() {
		return Err(Error::invalid_argument(
			"image::fill_polygon color must be finite",
		));
	}
	if points.dtype() != DType::F32 {
		return Err(Error::invalid_argument(
			"image::fill_polygon points must be f32",
		));
	}
	if !input.runtime().same_as(points.runtime()) {
		return Err(Error::invalid_argument(
			"image::fill_polygon points must share the input runtime",
		));
	}
	if points.shape().len() != 2 || points.shape()[1] != 2 || points.shape()[0] < 3 {
		return Err(Error::invalid_argument(
			"image::fill_polygon points must have shape [N, 2] with N >= 3",
		));
	}
	let point_count_u32 = u32::try_from(points.shape()[0])
		.map_err(|_| Error::out_of_range("image::fill_polygon point count exceeds u32"))?;
	let (batch, channels, image_height, image_width) = image_extent(input, contract.name())?;
	let element_count = u32::try_from(input.as_matrix().num_elements())
		.map_err(|_| Error::out_of_range("image::fill_polygon element count exceeds u32"))?;
	let matrix = crate::Matrix::allocate(
		input.runtime(),
		input.as_matrix().shape().to_vec(),
		input.as_matrix().num_elements(),
		DType::F32,
	)?;
	let output = Image::new(matrix, input.layout(), input.format())?;
	input.runtime().record_image_semantic(
		ComputeDispatch {
			kernel: KernelId::ImageFillPolygonF32,
			buffers: &[
				BufferBinding::read(input.storage()),
				BufferBinding::read(points.storage()),
				BufferBinding::write(output.storage()),
			],
			push_constants: &[
				PushConstant::U32(batch),
				PushConstant::U32(channels),
				PushConstant::U32(element_count),
				PushConstant::U32(image_height),
				PushConstant::U32(image_width),
				PushConstant::U32(point_count_u32),
				PushConstant::F32(color),
			],
			workgroups: KernelId::ImageFillPolygonF32.linear_workgroups(element_count),
			indirect: None,
		},
		ImageSemanticDispatch {
			contract,
			inputs: &[
				ImageSemanticInput::Image(input),
				ImageSemanticInput::Matrix(points),
			],
			outputs: &[ImageSemanticOutput::Image(&output)],
			attributes: &[float("color", color)],
		},
	)?;
	Ok(output)
}

fn validate_matching_images(a: &Image, b: &Image, operation: &str) -> Result<()> {
	image_extent(a, operation)?;
	if a.as_matrix().shape() != b.as_matrix().shape()
		|| a.dtype() != b.dtype()
		|| a.layout() != b.layout()
		|| a.format() != b.format()
		|| !a.runtime().same_as(b.runtime())
	{
		return Err(Error::invalid_argument(format!(
			"{operation} images must have identical shape, dtype, layout, format, and runtime"
		)));
	}
	Ok(())
}

fn image_extent(input: &Image, operation: &str) -> Result<(u32, u32, u32, u32)> {
	if input.dtype() != DType::F32 || !matches!(input.layout(), ImageLayout::Nchw | ImageLayout::Chw)
	{
		return Err(Error::invalid_argument(format!(
			"{operation} requires an FP32 NCHW or CHW image"
		)));
	}
	let extent = (
		u32::try_from(input.batch_size()),
		u32::try_from(input.channels()),
		u32::try_from(input.height()),
		u32::try_from(input.width()),
	);
	let (batch, channels, height, width) = match extent {
		(Ok(batch), Ok(channels), Ok(height), Ok(width)) => (batch, channels, height, width),
		_ => {
			return Err(Error::out_of_range(format!(
				"{operation} extent exceeds u32"
			)));
		}
	};
	if batch == 0 || channels == 0 || height == 0 || width == 0 {
		return Err(Error::invalid_argument(format!(
			"{operation} requires a nonempty image"
		)));
	}
	Ok((batch, channels, height, width))
}

fn allocate(
	input: &Image,
	shape: Vec<usize>,
	format: ImageFormat,
	operation: &str,
) -> Result<Image> {
	let elements = shape.iter().copied().try_fold(1_usize, |count, extent| {
		count
			.checked_mul(extent)
			.ok_or_else(|| Error::out_of_range(format!("{operation} output size exceeds usize")))
	})?;
	u32::try_from(elements)
		.map_err(|_| Error::out_of_range(format!("{operation} output size exceeds u32")))?;
	let matrix = Matrix::allocate(input.runtime(), shape, elements, DType::F32)?;
	Image::new(matrix, input.layout(), format)
}

#[allow(clippy::too_many_arguments)]
fn finite(values: &[f32], operation: &str) -> Result<()> {
	if values.iter().all(|value| value.is_finite()) {
		Ok(())
	} else {
		Err(Error::invalid_argument(format!(
			"{operation} parameters must be finite"
		)))
	}
}

fn float(name: &str, value: f32) -> OpAttribute {
	OpAttribute::Float {
		name: name.into(),
		value: f64::from(value),
	}
}

fn unsigned(name: &str, value: u32) -> OpAttribute {
	OpAttribute::UnsignedInteger {
		name: name.into(),
		value: u64::from(value),
	}
}

fn unsigned64(name: &str, value: u64) -> OpAttribute {
	OpAttribute::UnsignedInteger {
		name: name.into(),
		value,
	}
}

fn enumeration(name: &str, value: &str) -> OpAttribute {
	OpAttribute::Enum {
		name: name.into(),
		value: value.into(),
	}
}

const fn image_format_token(format: ImageFormat) -> &'static str {
	match format {
		ImageFormat::Gray => "gray",
		ImageFormat::GrayAlpha => "gray_alpha",
		ImageFormat::Rgb => "rgb",
		ImageFormat::Rgba => "rgba",
		ImageFormat::Bgr => "bgr",
		ImageFormat::Bgra => "bgra",
	}
}
